// A seat kept running past its run is checked again this soon for unread mail and other work.
// Reading a conversation message does not wake the reconciler, so this check is what lets the
// stop go ahead. Each check is a pass: at 10 s, held seats were the most frequent wake on a busy
// member. A held seat stops at most a minute after its last reason goes.
const SEAT_RETENTION_CHECK_MS: u128 = 60_000;
// Report a retained stop after this age; this is never a termination deadline.
const STOP_DEFERRAL_FAULT_MS: u128 = 15 * 60 * 1000;
// Run cleanup ends this long after it began even if an owned runtime never reports stopped.
const CLEANUP_DEADLINE: Duration = Duration::from_secs(15 * 60);
const DECLARED_CHECKOUT_LIMIT: usize = 4096;

/// `local` is the declaration's origin, not the member interpreting a replicated declaration.
fn owned_schedule_spec(
    store: &Store,
    schedule: &DesiredSubject,
) -> Result<Option<crate::model::ScheduleSpec>> {
    let Some(origin) = store.selected_desired_origin(&schedule.subject)? else {
        return Ok(None);
    };
    Ok(crate::graph::schedule_spec(&schedule.desired, &origin))
}

/// The largest occurrence reached by this schedule's stable identity: whole history, which
/// both hosts write and catch-up can skip. A run that supersedes another starts under a new
/// run subject, so its schedule continues the history of the same-named schedule in every
/// run it supersedes; publishing a new parent revision never replays a reached tick.
fn schedule_last_reached(store: &Store, schedule: &DesiredSubject) -> Result<Option<u64>> {
    let mut subjects = vec![schedule.subject.clone()];
    if let Some(owner) = schedule.owner_run.as_deref() {
        let owner = owner.strip_prefix("mission-run/").unwrap_or(owner);
        if let Some(local) = schedule.subject.strip_prefix(&format!("schedule/{owner}/")) {
            for ancestor in store.mission_run_supersession_ancestry(owner)?.into_iter().skip(1) {
                let ancestor = ancestor.strip_prefix("mission-run/").unwrap_or(&ancestor);
                subjects.push(format!("schedule/{ancestor}/{local}"));
            }
        }
    }
    let mut last = None;
    for subject in subjects {
        for claim in store.claims_for(&subject, Some("schedule.occurrence-reached"))? {
            last = last.max(claim.body["fields"]["occurrence"].as_u64());
        }
    }
    Ok(last)
}

/// On a fleet member's cold start, occurrence history may still be elsewhere. Require a fresh
/// complete exchange before admitting schedules, then hold while known history is missing.
fn schedule_admission_ready(
    store: &Store,
    host: &str,
    configured: &[String],
    since: u128,
    schedule: &DesiredSubject,
) -> Result<bool> {
    // Include the due callback: an armed timer cannot bypass a staged or conflicting owner.
    store.owned_desired_guard(schedule).map_err(anyhow::Error::new)?;
    if store.replication_projection_deferred()
        || store.replication_catching_up()
        || store
            .first_sync()?
            .is_some_and(|sync| sync.state == "syncing")
    {
        return Ok(false);
    }
    let peers = schedule_admission_peers(store, host, configured)?;
    if peers.is_empty() {
        return Ok(true);
    }
    let sync = store.replication_peer_sync(&peers);
    let strict = sync.values().any(|peer| peer.stale && peer.peer_only_envelopes > 0)
        && schedule_requires_complete_history(store, schedule)?;
    Ok(schedule_progress_ready(sync.values(), since, strict))
}

fn schedule_admission_peers(store: &Store, host: &str, configured: &[String]) -> Result<Vec<String>> {
    let membership = store.fleet_membership()?;
    Ok(configured.iter().cloned()
        .chain(membership.incarnations().filter(|member| member.end.is_none())
            .map(|member| member.name.clone()))
        .filter(|peer| peer != host && !matches!(membership.state(peer),
            crate::fleet::MemberState::Ended(_) | crate::fleet::MemberState::LegacyRemoved(_)))
        .collect::<BTreeSet<_>>().into_iter().collect())
}

/// Moving a schedule (or removing its standby) must not turn an old missing-history
/// comparison into permission to run on a second host. Retain the strict policy after
/// any role, owning run, or declaring step change. Revising the same owning run changes
/// its generation, not its ownership, and does not require complete history.
fn schedule_requires_complete_history(store: &Store, schedule: &DesiredSubject) -> Result<bool> {
    let Some(current) = owned_schedule_spec(store, schedule)? else { return Ok(true) };
    if current.standby.is_some() { return Ok(true); }
    // The first earlier declaration that differs, or that does not parse, decides it.
    let differs = store.oldest_claim_where(&schedule.subject, "intent.desired", |claim| {
        let Some(previous) = crate::graph::schedule_spec(&claim.body["desired"], &claim.origin) else {
            return true;
        };
        previous.host != current.host || previous.standby.is_some()
            || claim.body["owner_run"].as_str() != schedule.owner_run.as_deref()
            || claim.body["owner_step"].as_str() != schedule.owner_step.as_deref()
    })?;
    Ok(differs.is_some())
}

fn schedule_progress_ready<'a>(
    sync: impl IntoIterator<Item = &'a smallclaims::replication::ReplicationPeerSync>,
    since: u128,
    strict: bool,
) -> bool {
    let mut complete = false;
    for peer in sync {
        if peer.peer_only_envelopes > 0 && (strict || !peer.stale) { return false; }
        complete |= peer.measured_at_unix_ms >= since && peer.peer_only_envelopes == 0;
    }
    complete
}

